const body = $input.first().json.body;
const errors = [];

const required = [
  'job_id',
  'schedule_id',
  'notification_type',
  'occurrence_date',
  'send_at',
  'recipient_email',
  'dedupe_key',
  'message'
];

const data = body && typeof body === 'object'
  && !Array.isArray(body) ? body : {};

for (const field of required) {
  if (data[field] === undefined ||
      data[field] === null ||
      data[field] === '') {
    errors.push(`Missing field: ${field}`);
  }
}

for (const field of Object.keys(data)) {
  if (!required.includes(field)) {
    errors.push(`Unexpected field: ${field}`);
  }
}

for (const field of ['job_id', 'schedule_id']) {
  if (!Number.isInteger(data[field]) || data[field] <= 0) {
    errors.push(`Invalid ${field}`);
  }
}

if (!['d1', 'day_of'].includes(data.notification_type)) {
  errors.push('Invalid notification_type');
}

if (!/^\d{4}-\d{2}-\d{2}$/.test(data.occurrence_date || '') ||
    Number.isNaN(Date.parse(data.occurrence_date))) {
  errors.push('Invalid occurrence_date');
}

if (Number.isNaN(Date.parse(data.send_at))) {
  errors.push('Invalid send_at');
}

if (!/^[^@\s]+@example\.test$/i.test(data.recipient_email || '')) {
  errors.push('Use a test email address');
}

if (!/^[a-f0-9]{64}$/.test(data.dedupe_key || '')) {
  errors.push('Invalid dedupe_key');
}

if (typeof data.message !== 'string' ||
    !data.message.trim()) {
  errors.push('Invalid message');
}

return [{
  json: {
    success: errors.length === 0,
    service: 'TWO PICK',
    mode: 'webhook_test',
    status_code: errors.length === 0 ? 200 : 400,
    message: errors.length === 0
      ? 'Webhook received successfully'
      : 'Validation failed',
    errors,
    received_at: new Date().toISOString()
  }
}];
